import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define fused activation kernel combining ReLU and HardSwish
fused_activation_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_activation_kernel(const float* input, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx];
        // ReLU
        val = fmaxf(val, 0.0f);
        // HardSwish components
        float shifted = val + 3.0f;
        shifted = fminf(fmaxf(shifted, 0.0f), 6.0f);
        output[idx] = val * (shifted / 6.0f);
    }
}

torch::Tensor fused_activation_cuda(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();

    const int block_size = 256;
    dim3 grid((num_elements + block_size - 1) / block_size);

    fused_activation_kernel<<<grid, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}
"""

fused_activation_cpp = "torch::Tensor fused_activation_cuda(torch::Tensor input);"

# Load custom fused activation CUDA extension
fused_activation = load_inline(
    name='fused_activation',
    cpp_sources=fused_activation_cpp,
    cuda_sources=fused_activation_source,
    functions=['fused_activation_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.activation = fused_activation.fused_activation_cuda

    def forward(self, x):
        x = self.conv(x)
        x = self.activation(x)
        return x
